			            // 상담자할당 권한 ▷ 그룹권한구분코드 340(기관-담당자)아닌 경우만 권한 부여
			            if (userGroupAuthrt != 340) {
			                util.Control.setEnable(app, true, ["grpCnsltntAsgn"]);
			            } else {
			                util.Control.setEnable(app, false, ["grpCnsltntAsgn"]);
			            }
			            
			            // 상담자할당 근무일자 ▷ 할당된 근무일자가 존재하면 setValue 후 서브미션(subInsertCounselor) 호출
