			function cmbAcbgSelectionChange(psState){
			    
			    var vcAcbgCombo = app.lookup("cmbAcbg");        // 학력구분
			    var vcGradeCombo = app.lookup("cmbGrade");      // 학년구분
			    var vcGrdtnCombo = app.lookup("cmbGrdtn");      // 졸업상태구분
			    
			    console.log("psState ::: " + psState);
			    if (psState != "UPDATE") {
			        vcGradeCombo.value = "";     // 학년구분 초기화
			        vcGrdtnCombo.value = "";    // 졸업상태구분 초기화
			    }
			    
			    var vcAcbgComboVal = vcAcbgCombo.value;
			    console.log("vcAcbgComboValue ::: " + vcAcbgComboVal);
			    
			    if (vcAcbgComboVal == '0' || vcAcbgComboVal == '01' || vcAcbgComboVal == '91' || vcAcbgComboVal == '92' || vcAcbgComboVal == '') {
			        vcGradeCombo.enabled = false;
			    } else {
			        vcGradeCombo.enabled = true;
			    }
			    
			    vcGrdtnCombo.enabled = false;
			    
			    switch (vcAcbgComboVal) {
			        case "01": // 미취학
			        case "91": // 무학
			        case "92": // 무응답
			            vcGradeCombo.value = ""; // 학년구분
			            break;
			        case "02": // 초등학교
			            vcGradeCombo.filterExp = "value == '' || value < 7";
			            break;
			        case "03": // 중학교
			        case "04": // 고등학교
			            vcGradeCombo.filterExp = "value == '' || value < 4";
			            break;
			        case "05": // 대학
			            vcGradeCombo.filterExp = "value == '' || value < 5";
			            break;
			        case "06": // 대학원            
			        case "07": // 전문대
			            vcGradeCombo.filterExp = "value == '' || value < 3";
			            break;
			    }
			}

