			/*
			 * "저장" 버튼(btnSave)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnSaveClick(e){
			    var btnSave = e.control;
			    
			    var userGroupAuthrt = user["GROUP_AUTHRT_SE_CD"];
			    var checkYN = false;
			    var replyCheckYN = false;
			    
			    /*
			     * validation Check
			     * 1. 내담자 성별 - AYE100 ok
			     * 2. 답글 제목 - AYE120 ok
			     * 3. 답글 내용 - AYE120 ok  
			     * 4. 게시글에 있는 메모 작성 or 변경 여부 체크 ok
			     */
			    
			    var dsBoardList = app.lookup("dsBoardList");
			    var dsDtlReply = app.lookup("dsDtlReply");
			    var vcReplyTitle = app.lookup("ipbReplyTitle");
			    var vcHtmlEditor = app.lookup("cmnHtmlEditor3");
			    
			    var preMemoCn = dsBoardList.getOriginalValue(0, "MEMO_NM");
			    var nextMemoCn = app.lookup("cmnAutoHeightTextarea1").value;
			    
			    console.log("preMemoCn ::: " + preMemoCn);
			    console.log("nextMemoCn ::: " + nextMemoCn);
			    
			    var preReplyTitleVal = dsDtlReply.getOriginalValue(0, "RETE_TTL_NM");
			    var nextReplyTitleVal = vcReplyTitle.value;
			    
			    var preReplyContent = dsDtlReply.getValue(0, "RETE_CN");
			    var nextReplyContent = vcHtmlEditor.getValue();
			    
			    console.log("nextReplyContent ::: " + nextReplyContent);
			    console.log("nextReplyContent.length ::: " + nextReplyContent.length);
			    
			    // 답글 내용 최초 작성시 공백 제거
			    var removeGapContent = "";
			    var splitReplyContent = nextReplyContent.split("&nbsp;");
			    splitReplyContent.some(function(each){
			        if (each.trim().length > 0) {
			            removeGapContent += each;
			        }
			    });
			    
			    if (!checkYN) {
			        if (nextReplyTitleVal != preReplyTitleVal) {
			            checkYN = true;
			        }
			        
			        if (nextReplyContent != preReplyContent) {
			            checkYN = true;
			        }
			    }
			    
			    if (checkYN) {
			        if (!util.validate(app, "rdbSxdc")) return false;
			        if (!util.validate(app, "ipbReplyTitle")) {
			            return false;
			        } else {
			            if (nextReplyTitleVal.trim().length == 0) {
			                util.Msg.alert(app, "WRN-M001", "답글 제목", function() {
			                    vcReplyTitle.focus();
			                }, "알림");
			                return false;
			            }
			        }
			        if (removeGapContent.length == 0) {
			            util.Msg.alert(app, "WRN-M001", "답글 내용", null, "알림");
			            return false;
			        } else {
			            if (nextReplyContent != preReplyContent) {
			                console.log("답글 변경한다~~~");
			                dsDtlReply.setValue(0, "RETE_CN", nextReplyContent);
			            }
			        }
			        
			        replyCheckYN = true;
			    }

			    console.log("게시글(원글) 변경사항 Check ::: " + dsBoardList.isModified());
			    console.log("답글 변경사항 Check ::: " + dsDtlReply.isModified());
			    console.log("답글 변경사항 Check ::: " + replyCheckYN);
			    
			    if (dsBoardList.isModified() || replyCheckYN) {
			        util.Msg.confirm(app, "CRM-M001", null, function() {
			            // 메모 저장
			            if (nextMemoCn.trim().length > 0) {
			                if (nextMemoCn != preMemoCn) {
			                    console.log("메모 저장한다~~~");
			                    util.Submit.send(app, "subInsertMemo", function(pbSuccess) {
			                        
			                    });
			                }
			            }
			            
			            util.Submit.send(app, "subDtlSaveAll", function(pbSuccess) {
			                if (pbSuccess) {
			                    // CRUD에 따른 화면 구성 함수
			                    setDtlCrud("READ");
			                    
			                    // 게시글(원글) 및 답글 재조회
			                    doDtlList("save");
			                }
			            });
			        }, null, "안내");
			    } else {
			        util.Msg.alert(app, "INF-M006", null, function() {
			            
			        }, "알림");
			    }
			}

